```javascript
import { Group, Mesh, PlaneGeometry, RingGeometry, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, DirectionalLight, AmbientLight } from 'three/webgpu';
import { uv, mix, smoothstep, length, abs, fract, min, float, color, oneMinus } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    gradientStops,
    colors,
    typography
  } = config.intent.visualSpec;

  const group = new ctx.THREE.Group();
  group.position.set(0, 0.2, 0);
  group.scale.setScalar(0.98);

  // Stage Backdrop & Lighting
  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    new MeshBasicNodeMaterial({
      colorNode: mix(color(colors.background), color(gradientStops[0].hex), oneMinus(length(uv().sub(0.5)).mul(1.5))),
      transparent: true
    })
  );
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  const keyLight = new ctx.THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(3, 4, 3);
  const rimLight = new ctx.THREE.DirectionalLight(new Color(colors.accent), 0.6);
  rimLight.position.set(-3, -2, 2);
  const ambient = new ctx.THREE.AmbientLight(0x404050, 0.6);
  group.add(keyLight, rimLight, ambient);

  // 1. Main Panel
  const panelWidth = 3.2;
  const panelHeight = 2.2;
  const panel = new Mesh(new PlaneGeometry(panelWidth, panelHeight));

  const uCell = float(panelWidth).div(0.25);
  const vCell = float(panelHeight).div(0.25);
  const gridU = fract(uv().x.mul(uCell));
  const gridV = fract(uv().y.mul(vCell));
  const distToLine = min(abs(gridU.sub(0.5)), abs(gridV.sub(0.5)));
  const gridLine = oneMinus(smoothstep(float(0.02), float(0.03), distToLine));

  const baseColor = mix(color(gradientStops[0].hex), color(gradientStops[1].hex), length(uv().sub(0.5)).mul(2.0));

  panel.material = new MeshStandardNodeMaterial({
    colorNode: baseColor,
    roughnessNode: mix(float(0.7), float(0.3), gridLine),
    metalnessNode: mix(float(0.0), float(0.4), gridLine),
    transparent: true,
    opacity: 0
  });
  group.add(panel);

  // 2. Panel Border
  const borderMat = new MeshBasicNodeMaterial({
    colorNode: color('#26262f'),
    transparent: true,
    opacity: 0
  });
  const bSize = 0.006;
  const borderT = new Mesh(new PlaneGeometry(panelWidth, bSize), borderMat);
  borderT.position.y = panelHeight / 2 - bSize / 2;
  const borderB = new Mesh(new PlaneGeometry(panelWidth, bSize), borderMat);
  borderB.position.y = -panelHeight / 2 + bSize / 2;
  const borderL = new Mesh(new PlaneGeometry(bSize, panelHeight), borderMat);
  borderL.position.x = -panelWidth / 2 + bSize / 2;
  const borderR = new Mesh(new PlaneGeometry(bSize, panelHeight), borderMat);
  borderR.position.x = panelWidth / 2 - bSize / 2;
  group.add(borderT, borderB, borderL, borderR);

  // 3. Ghost Preview
  const ghostGroup = new ctx.THREE.Group();
  ghostGroup.position.x = -0.8;
  group.add(ghostGroup);

  const ghostMat = new MeshBasicNodeMaterial({
    colorNode: new Color(colors.paper),
    transparent: true,
    opacity: 0
  });
  const ghostCardMat = ghostMat.clone();
  ghostCardMat.colorNode = new Color(colors.paper).mul(0.3);

  const ghostBorder = new Mesh(new PlaneGeometry(1.1, 0.008), ghostCardMat);
  const ghostBorder2 = new Mesh(new PlaneGeometry(1.1, 0.008), ghostCardMat);
  const ghostBorder3 = new Mesh(new PlaneGeometry(0.008, 1.4), ghostCardMat);
  const ghostBorder4 = new Mesh(new PlaneGeometry(0.008, 1.4), ghostCardMat);
  ghostBorder.position.y = 0.7 - 0.004;
  ghostBorder2.position.y = -0.7 + 0.004;
  ghostBorder3.position.x = -0.55 + 0.004;
  ghostBorder4.position.x = 0.55 - 0.004;
  ghostGroup.add(ghostBorder, ghostBorder2, ghostBorder3, ghostBorder4);

  const ghostDial = new Mesh(new RingGeometry(0.27, 0.278, 48), ghostCardMat);
  ghostDial.position.z = 0.01;
  ghostDial.scale.y = -1; // Correct winding if needed
  ghostGroup.add(ghostDial);

  const ghostBar1 = new Mesh(new PlaneGeometry(0.7, 0.06), new MeshBasicNodeMaterial({
    colorNode: new Color(colors.paper).mul(0.22),
    transparent: true,
    opacity: 0
  }));
  ghostBar1.position.set(0, -0.35, 0.01);
  const ghostBar2 = ghostBar1.clone();
  ghostBar2.position.set(0, -0.45, 0.01);
  ghostGroup.add(ghostBar1, ghostBar2);

  // 4. Text Column
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let headlineText = items.find(i => i.role === 'headline')?.text || "Your ledger is empty.";
  let bodyText = items.find(i => i.role === 'body')?.text || "Commissioned pieces and saved references will appear here once you begin.";
  let ctaText = items.find(i => i.role === 'cta-label')?.text || "BROWSE THE COLLECTION";

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 0.34,
    color: colors.paper,
    align: 'left'
  });
  headline.position.set(0.25, 0.5, 0.02);
  group.add(headline);

  const body = ctx.fontAtlas.createText(bodyText, {
    fontSize: 0.13,
    color: '#c9cdd6',
    align: 'left',
    maxWidthPx: 200
  });
  body.position.set(0.25, 0.2, 0.02);
  group.add(body);

  // 5. CTA Button
  const ctaGroup = new ctx.THREE.Group();
  ctaGroup.position.set(1.0, -0.7, 0.02);
  group.add(ctaGroup);

  const ctaBack = new Mesh(
    new PlaneGeometry(1.54, 0.40),
    new MeshBasicNodeMaterial({
      colorNode: new Color(colors.accent).mul(1.5),
      transparent: true,
      opacity: 0
    })
  );
  ctaBack.position.z = -0.01;
  ctaGroup.add(ctaBack);

  const ctaButton = new Mesh(
    new PlaneGeometry(1.5, 0.36),
    new MeshStandardNodeMaterial({
      colorNode: mix(new Color('#c1121f'), new Color('#ff4450'), uv().y),
      transparent: true,
      opacity: 0,
      roughness: 0.3,
      metalness: 0.2
    })
  );
  ctaGroup.add(ctaButton);

  const ctaLabel = ctx.fontAtlas.createText(ctaText, {
    fontSize: 0.13,
    color: colors.ink,
    align: 'center',
    letterSpacingPx: 1.0
  });
  ctaLabel.position.z = 0.1;
  ctaGroup.add(ctaLabel);

  // 6. Mount Animation
  const allMats = [];
  group.traverse(obj => {
    if (obj.isMesh || obj.material) {
      obj.traverse(m => {
        if (m.material) {
          const mats = Array.isArray(m.material) ? m.material : [m.material];
          mats.forEach(mat => {
            if (!mat._tracked) {
              mat.transparent = true;
              mat._origOpacity = mat.opacity === 0 ? 1 : mat.opacity; // Target ghost is 0.24, CTA is 1
              if (mat === ghostCardMat) mat._origOpacity = 0.3;
              if (mat === ghostBar1.material) mat._origOpacity = 0.22;
              if (mat === ctaBack.material) mat._origOpacity = 1;
              if (mat === ctaButton.material) mat._origOpacity = 1;
              if (mat === panel.material) mat._origOpacity = 1;
              if (mat === borderMat) mat._origOpacity = 1;
              mat.opacity = 0;
              allMats.push(mat);
              mat._tracked = true;
            }
          });
        }
      });
    }
  });

  // fix text material tracking
  const textMeshes = [headline, body, ctaLabel];
  textMeshes.forEach(t => {
    if (t.isMesh && t.material && !t.material._tracked) {
      t.material.transparent = true;
      t.material._origOpacity = 1;
      t.material.opacity = 0;
      allMats.push(t.material);
      t.material._tracked = true;
    } else if (t.children) {
      t.children.forEach(c => {
        if (c.material && !c.material._tracked) {
          c.material.transparent = true;
          c.material._origOpacity = 1;
          c.material.opacity = 0;
          allMats.push(c.material);
          c.material._tracked = true;
        }
      });
    }
  });

  gsap.to(group.position, { y: 0, duration: 0.5, ease: "power2.out" });
  gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: "power2.out" });
  gsap.to(allMats, { opacity: (i, t) => t._origOpacity, duration: 0.5, ease: "power2.out", delay: 0.05 });

  // Ghost Breathing
  gsap.to(ghostCardMat, { opacity: 0.34, duration: 1.2, yoyo: true, repeat: -1, ease: "sine.inOut", delay: 0.55 });
  gsap.to(ghostBar1.material, { opacity: 0.26, duration: 1.2, yoyo: true, repeat: -1, ease: "sine.inOut", delay: 0.55 });
  gsap.to(ghostBar2.material, { opacity: 0.26, duration: 1.2, yoyo: true, repeat: -1, ease: "sine.inOut", delay: 0.55 });

  // 7. Interactions
  group.userData.handlers = {
    pointerdown: () => gsap.to(ctaGroup.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: "back.out(1.9)" }),
    pointerup: () => gsap.to(ctaGroup.scale, { x: 1, y: 1, duration: 0.2, ease: "back.out(1.9)" }),
    click: () => ctx.emit('navigate', { to: 'hub-collection' })
  };

  // 8. Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(ctaGroup.scale);
    gsap.killTweensOf(ghostCardMat);
    gsap.killTweensOf(ghostBar1.material);
    gsap.killTweensOf(ghostBar2.material);
    gsap.killTweensOf(allMats);

    group.traverse(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        mats.forEach(m => m.dispose());
      }
    });
  };

  return group;
}
